-- MU GKZ: Arena as the spot of the freshly reset characters (level 1 after the reset): packs of Lost Tower monsters
-- (level 57-62) next to the arrival point, and of Tarkan/Aida monsters (level 83-84) in the east column; warp from level 1.
\set ON_ERROR_STOP on
begin;
update config."WarpInfo" set "LevelRequirement" = 1 where "Index" = 1;
-- Idempotent: the packs of this script are created again.
delete from config."MonsterSpawnArea" sa using config."GameMapDefinition" m where m."Id" = sa."GameMapId" and m."Number" = 6 and sa."SpawnTrigger" = 0
  and sa."MonsterDefinitionId" in (select "Id" from config."MonsterDefinition" where "Number" in (41, 37, 40, 58, 61, 305));
select split_part(md."Designation", '||', 1) as monster, sum(sa."Quantity") from config."MonsterSpawnArea" sa join config."MonsterDefinition" md on md."Id" = sa."MonsterDefinitionId" join config."GameMapDefinition" m on m."Id" = sa."GameMapId" where m."Number" = 6 group by 1;
select "LevelRequirement" from config."WarpInfo" where "Index" = 1;
commit;
